const icons={arrow:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg>', arrowDiag:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19 19 5M7 5h12v12"/></svg>',plus:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4v16M4 12h16"/></svg>',close:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 5l14 14M19 5 5 19"/></svg>',chev:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 9 7 7 7-7"/></svg>',calendar:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/></svg>'};
function img(src,backup='portrait',className='',alt='',extra=''){
 const loading=extra.includes('loading=')?'':'loading="lazy"';
 const srcset=src.startsWith(P)?`srcset="${src.replace(/w=\d+/, 'w=480')} 480w, ${src.replace(/w=\d+/, 'w=800')} 800w, ${src.replace(/w=\d+/, 'w=1200')} 1200w, ${src.replace(/w=\d+/, 'w=1600')} 1600w" sizes="(max-width: 760px) 100vw, (max-width: 1200px) 50vw, 38vw"`:'';
 return `<img class="${className}" src="${src}" ${srcset} data-fallback="${fallback[backup]}" alt="${alt}" ${loading} decoding="async" ${extra}>`;
}
function arrowLink(label,href,extra=''){return `<a href="${href}" data-link class="text-link ${extra}">${label}<span>${icons.arrowDiag}</span></a>`;}
function btn(label,extra=''){return `<button type="button" class="btn btn-primary ${extra}" data-book>${label} ${icons.arrowDiag}</button>`;}
function sectionLabel(text){return `<div class="eyebrow"><i></i>${text}</div>`;}
function header(path){const links=[['/','Home'],['/treatments','Treatments'],['/universe','The Universe'],['/gallery','Gallery'],['/about','Our Story']];return `<div class="concept-strip"><span>AN INDEPENDENT LUXURY AESTHETICS CONCEPT</span><span class="strip-stars">✳ &nbsp; DEMONSTRATION ONLY &nbsp; ✳</span></div><header class="site-header" id="site-header"><a data-link href="/" class="brand" aria-label="Aesthetics Universe home"><span class="brand-icon"><img src="/assets/symbol.svg" alt="" /></span><span class="brand-name">AESTHETICS<span>UNIVERSE</span></span></a><nav class="desktop-nav" aria-label="Main navigation">${links.map(([url,name])=>`<a data-link href="${url}" class="${path===url?'active':''}">${name}</a>`).join('')}</nav><div class="header-actions"><button class="header-book" data-book>BOOK A CONSULTATION <span>↗</span></button><button class="menu-toggle" aria-label="Open menu" aria-expanded="false" data-menu><span></span><span></span></button></div><nav class="mobile-nav" id="mobile-nav" aria-label="Mobile navigation">${links.map(([url,name],i)=>`<a data-link href="${url}"><span>0${i+1}</span>${name}${icons.arrowDiag}</a>`).join('')}<button data-book>Discover a consultation ↗</button></nav></header>`;}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-top"><div><a data-link href="/" class="brand footer-brand"><span class="brand-icon"><img src="/assets/symbol.svg" alt=""/></span><span class="brand-name">AESTHETICS<span>UNIVERSE</span></span></a><h3>Your beauty.<br><em>Your universe.</em></h3><p>A new perspective on the art of feeling like yourself.</p></div><div class="footer-links"><div><h4>EXPLORE</h4><a data-link href="/">Home</a><a data-link href="/treatments">Treatments</a><a data-link href="/universe">Explore your universe</a><a data-link href="/gallery">Gallery</a></div><div><h4>DISCOVER</h4><a data-link href="/about">Our story</a><a data-link href="/contact">Contact</a><a href="/contact" data-link>FAQs & enquiries</a><a href="/privacy" data-link>Privacy & terms</a><a href="/photography" data-link>Image credits</a><button data-book>Booking demo</button></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} AESTHETICS UNIVERSE. CONCEPT DESIGN.</span><span>DEMONSTRATION ONLY · NO REAL CLINIC OR APPOINTMENTS</span><form method="post" action="/__preview/logout" class="preview-logout"><button type="submit" aria-label="Lock the private preview and return to the Coming Soon page">LOCK PREVIEW ↗</button></form><a href="#top" data-top>BACK TO TOP ↑</a></div></div></footer><div class="mobile-sticky"><button data-book>Explore booking <span>↗</span></button></div>`;}
function card(t,index=0){return `<a class="treatment-card" data-link href="/treatments/${t.slug}" style="--delay:${index*70}ms"><div class="treatment-photo ${t.backup}">${img(t.image,t.backup,'',`${t.name} illustrative editorial photograph`)}<span class="card-index">0${index+1}</span><span class="card-arrow">${icons.arrowDiag}</span></div><div class="card-meta"><span>${t.tag}</span><span>DISCOVER ↗</span></div><h3>${t.name}</h3><p>${t.short}</p></a>`;}
function orbitArt(){return `<div class="hero-art"><div class="hero-art-glow"></div><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit orbit-three"></div><div class="hero-photo-frame">${img(PHOTOS.hero,'portrait','hero-portrait','Editorial beauty portrait','fetchpriority="high" loading="eager"')}<div class="photo-shade"></div></div><div class="hero-mini-star">✳</div><div class="hero-floating-note"><span class="little-sun">✳</span><div>BEAUTY IN EVERY<br><strong>DIMENSION</strong></div></div><div class="orbit-label label-top">EXPERIENCE THE EXTRAORDINARY</div><div class="orbit-label label-bottom">A UNIVERSE OF POSSIBILITY • 001</div></div>`;}
function hero(){return `<section class="hero section-dark" id="top"><div class="hero-grid container"><div class="hero-copy"><div class="hero-eyebrow"><span class="gold-line"></span> A NEW PERSPECTIVE ON BEAUTY</div><h1>Your beauty.<br><span class="hero-italic">Your <em>universe.</em></span></h1><p>Where the art of aesthetics meets the beauty of being entirely, unapologetically you.</p><div class="hero-buttons"><a class="btn btn-light" data-link href="/universe">EXPLORE YOUR UNIVERSE ${icons.arrowDiag}</a><a class="subtle-cta" data-link href="/treatments"><span class="tiny-orbit">↗</span> DISCOVER TREATMENTS</a></div><div class="hero-bottom"><span>DESIGNED AROUND YOU<br><b>FROM THE VERY BEGINNING</b></span><span class="scroll-indicator">SCROLL TO EXPLORE <span>↓</span></span></div></div>${orbitArt()}</div><div class="hero-number">01 <span> / </span> ∞</div></section>`;}
function marquee(){return `<div class="marquee"><div class="marquee-content">${Array(2).fill(`<span>SKIN</span><b>✳</b><span>SCIENCE</span><b>✳</b><span>SOUL</span><b>✳</b><span>YOUR OWN KIND OF BEAUTY</span><b>✳</b>`).join('')}</div></div>`;}
function intro(){return `<section class="intro section-light"><div class="container intro-grid"><div class="intro-side">${sectionLabel('WELCOME TO A DIFFERENT WORLD')}<span class="intro-spark">✳</span></div><div class="intro-main"><h2>Beauty is not one-size-fits-all.<br><em>It’s a universe of its own.</em></h2><div class="intro-bottom"><p>We believe great aesthetics begins with curiosity, care and an appreciation of what makes you unique. Discover a more considered way to explore what is possible.</p>${arrowLink('OUR PHILOSOPHY','/about')}</div></div></div></section>`;}
function photoEditorial(){return `<section class="photo-editorial section-light" aria-labelledby="editorial-title"><div class="container"><div class="editorial-heading"><div>${sectionLabel('THE AESTHETICS EDIT')}<h2 id="editorial-title">A world of<br><em>beautiful detail.</em></h2></div><p>A considered collection of skincare rituals, facial aesthetics and moments made for you. Discover the artistry behind every thoughtful choice.</p></div><div class="editorial-gallery"><a class="editorial-main" data-link href="/treatments">${img(PHOTOS.facial,'interior','','A client receiving a professional facial skincare treatment')}<span><small>01 / SKIN HEALTH</small><strong>Care that begins<br>with understanding.</strong><i>EXPLORE SKIN TREATMENTS ↗</i></span></a><div class="editorial-side"><a class="editorial-small" data-link href="/about">${img(PHOTOS.serenity,'interior','','Warmly lit spa treatment environment')}<span><small>02 / THE EXPERIENCE</small><strong>Space to feel restored.</strong></span></a><a class="editorial-small" data-link href="/treatments">${img(PHOTOS.products,'serum','','A selection of skincare serums in warm studio light')}<span><small>03 / THE RITUAL</small><strong>Little details. Lasting impressions.</strong></span></a></div></div><div class="editorial-end"><span>REAL EDITORIAL PHOTOGRAPHY · ILLUSTRATIVE, NOT OUR CLINIC OR PATIENTS</span>${arrowLink('EXPLORE THE COLLECTION','/treatments')}</div></div></section>`;}
function universeGraphic(){return `<div class="universe-graphic"><div class="map-ring ring1"></div><div class="map-ring ring2"></div><div class="map-ring ring3"></div><div class="galaxy-core"><span class="core-star">✳</span><span>THE<br>UNIVERSE</span></div>${galaxies.map(g=>`<button type="button" class="galaxy-node ${selectedGalaxy===g.id?'selected':''}" data-galaxy="${g.id}" style="left:${g.x}%;top:${g.y}%" aria-pressed="${selectedGalaxy===g.id}"><span>${g.number}</span><b>${g.name}</b></button>`).join('')}<div class="map-caption">SELECT YOUR ORBIT · DISCOVER YOUR PATH</div></div>`;}
function galaxyPanel(g){return `<div class="galaxy-detail"><span class="galaxy-count">UNIVERSE / ${g.number} OF 04</span>${sectionLabel(g.eyebrow)}<h3>${g.title}</h3><p>${g.text}</p><div class="galaxy-tags">${g.links.map(slug=>{const t=treatments.find(t=>t.slug===slug);return `<a data-link href="/treatments/${t.slug}">${t.name} ↗</a>`;}).join('')}</div>${arrowLink('VIEW ALL TREATMENTS','/treatments')}</div>`;}
function universeSection(standalone=false){let g=galaxies.find(g=>g.id===selectedGalaxy)||galaxies[0];return `<section class="universe-section section-cream ${standalone?'standalone':''}" id="universe"><div class="container"><div class="section-heading split-heading"><div>${sectionLabel('THE UNIVERSE IS YOURS')}<h2>Find your own<br><em>beautiful orbit.</em></h2></div><p>Every face has its own story. Explore our treatment worlds and discover the possibilities that speak to yours.</p></div><div class="galaxy-mobile-picker" aria-label="Choose a treatment world">${galaxies.map(g=>`<button class="${selectedGalaxy===g.id?'active':''}" data-galaxy="${g.id}">${g.name}</button>`).join('')}</div><div class="universe-layout">${universeGraphic()}<div id="galaxy-panel">${galaxyPanel(g)}</div></div><div class="universe-bottom"><span>✳ &nbsp; AN EXPLORATION, NOT A TREATMENT RECOMMENDATION</span><a href="/contact" data-link>START WITH A CONVERSATION ↗</a></div></div></section>`;}
function featured(){return `<section class="featured section-dark"><div class="container"><div class="section-heading split-heading inverse"><div>${sectionLabel('THE TREATMENT COLLECTION')}<h2>Considered care.<br><em>Beautiful possibilities.</em></h2></div><div><p>Discover a curated introduction to aesthetic treatments, where informed choices and individuality take centre stage.</p>${arrowLink('VIEW ALL TREATMENTS','/treatments','on-dark')}</div></div><div class="treatment-grid">${[treatments[0],treatments[1],treatments[2],treatments[3]].map(card).join('')}</div></div></section>`;}
function storySlice(){return `<section class="story-slice section-light"><div class="story-photo">${img(PHOTOS.studio,'interior','', 'Beautifully designed beauty studio environment')}<span class="story-photo-title">a feeling of<br><em>possibility.</em></span><span class="photo-tag">THE ART OF FEELING YOU / 001</span></div><div class="story-content"><div class="story-content-inner">${sectionLabel('BEYOND THE ORDINARY')}<h2>Not about becoming someone else.<br><em>About discovering more of you.</em></h2><p>True beauty has never been about fitting a mould. It is found in the details, the differences and the quiet confidence of feeling comfortable in your own skin.</p><p>Our concept of aesthetics is personal, considered and always centred on the individual.</p>${arrowLink('GET TO KNOW OUR WORLD','/about')}</div><div class="story-signature">✳ &nbsp; THE BEAUTY OF INDIVIDUALITY</div></div></section>`;}
function process(){let items=[['01','Explore','Discover the treatments and ideas that interest you.'],['02','Connect','Begin with a thoughtful, professional conversation.'],['03','Consider','Understand possible options, alternatives and risks.'],['04','Feel you','Make informed choices, on your own terms.']];return `<section class="process section-cream"><div class="container"><div class="process-top">${sectionLabel('THE EXPERIENCE')}<h2>A journey as individual<br><em>as you are.</em></h2></div><div class="process-grid">${items.map(a=>`<div class="process-step"><span class="process-number">${a[0]} <span>✳</span></span><div class="process-rule"></div><h3>${a[1]}</h3><p>${a[2]}</p></div>`).join('')}</div></div></section>`;}
function galleryTeaser(){return `<section class="teaser section-light"><div class="container"><div class="section-heading split-heading"><div>${sectionLabel('A NEW WAY TO SEE BEAUTY')}<h2>Moments of<br><em>inspiration.</em></h2></div>${arrowLink('EXPLORE THE GALLERY','/gallery')}</div><div class="teaser-grid"><div class="teaser-one">${img(PHOTOS.products,'serum','', 'Luxury skincare editorial still life')}<span>01 / SKIN STORIES</span></div><div class="teaser-two">${img(PHOTOS.portraitSoft,'portrait','', 'Smiling woman with natural skin portrait')}<span>02 / BEAUTY IN DETAIL</span></div><div class="teaser-three">${img(PHOTOS.facial,'interior','', 'Skincare experience photograph')}<span>03 / THE EXPERIENCE</span></div></div><p class="fineprint">Editorial demonstration imagery only. No actual patient treatment results are depicted.</p></div></section>`;}
function sampleReview(){return `<section class="sample-review section-dark"><div class="container sample-review-inner"><div>${sectionLabel('A CLIENT VOICE — EXAMPLE COMPONENT')}<span class="review-stars" aria-label="Demonstration five star graphic">✳ &nbsp; ✳ &nbsp; ✳ &nbsp; ✳ &nbsp; ✳</span></div><blockquote>“For the first time, I felt that the conversation was about <em>me,</em> not about a trend.”</blockquote><div class="review-credit"><span>ILLUSTRATIVE TESTIMONIAL · NOT A REAL CUSTOMER REVIEW</span><span>01 / 01</span></div></div></section>`;}
function faqBlock(){return `<section class="faq-section section-cream"><div class="container faq-layout"><div>${sectionLabel('THE THINGS WORTH KNOWING')}<h2>Curious minds.<br><em>Welcome here.</em></h2><p>We believe informed decisions begin with the right questions.</p>${arrowLink('ASK A QUESTION','/contact')}</div><div class="faqs">${faqs.map(([q,a],i)=>`<details ${i===0?'open':''}><summary><span>0${i+1}</span>${q}<i>${icons.plus}</i></summary><p>${a}</p></details>`).join('')}</div></div></section>`;}
function ctaBand(){return `<section class="cta-band section-dark"><div class="cta-orbit cta-o1"></div><div class="cta-orbit cta-o2"></div><div class="container cta-inner">${sectionLabel('YOUR NEXT CHAPTER STARTS HERE')}<h2>Ready to explore<br><em>your universe?</em></h2><p>Wherever you are on your journey, curiosity is a beautiful place to begin.</p><button class="btn btn-light" data-book>EXPLORE BOOKING DEMO ${icons.arrowDiag}</button><span class="cta-disclaimer">ILLUSTRATIVE EXPERIENCE · NO APPOINTMENTS ARE BOOKED</span></div></section>`;}
function homePage(){return `${hero()}${marquee()}${intro()}${photoEditorial()}${universeSection()}${featured()}${storySlice()}${process()}${galleryTeaser()}${sampleReview()}${faqBlock()}${ctaBand()}`;}
function pageHero(eyebrow,title,italic,description,theme='dark'){return `<section class="page-hero section-${theme}"><div class="container"><div class="page-hero-inner">${sectionLabel(eyebrow)}<h1>${title}<br><em>${italic}</em></h1><p>${description}</p><div class="page-hero-icon">✳</div></div></div></section>`;}
function treatmentPage(){return `${pageHero('THE CURATED COLLECTION','Discover what','moves you.','A considered look at aesthetics, skincare and the confidence to make your own informed choices.')}<section class="catalogue section-light"><div class="container"><div class="catalogue-top"><p>EXPLORE BY CATEGORY</p><div class="filter-bar">${['All','Skin','Facial','Wellness'].map(c=>`<button class="filter-btn ${activeTreatments===c?'active':''}" data-treatment-filter="${c}">${c==='All'?'All treatments':c}</button>`).join('')}</div></div><div class="treatment-grid catalog-grid" id="catalogue-grid">${treatments.filter(t=>activeTreatments==='All'||t.category===activeTreatments).map(card).join('')}</div></div></section>${ctaBand()}`;}
function treatmentDetail(t){const related=treatments.filter(x=>x.category===t.category&&x.slug!==t.slug).slice(0,3);const questions=t.questions;return `<section class="detail-hero section-dark"><div class="container detail-layout"><div class="detail-copy"><a data-link href="/treatments" class="back-link">← &nbsp; ALL TREATMENTS</a>${sectionLabel(t.tag)}<h1>${t.name.replace(' ','<br>')}</h1><p>${t.desc}</p><div class="detail-tags"><span>${t.category.toUpperCase()}</span><span>PERSONALISED CONSULTATION</span></div>${btn('EXPLORE A CONSULTATION','detail-book')}</div><div class="detail-visual">${img(t.image,t.backup,'',`${t.name} editorial imagery`)}<div class="detail-frame"></div><span>THE TREATMENT COLLECTION / AU</span></div></div></section><section class="detail-info section-light"><div class="container info-grid"><div>${sectionLabel('THE OVERVIEW')}<h2>A considered<br><em>approach to care.</em></h2></div><div><p>${t.short} This demonstration page outlines general topics to explore, not individual medical advice or a clinical treatment recommendation.</p><p>A professional consultation should cover your goals, health history, possible benefits, limitations, alternatives, contraindications, costs and aftercare before you decide whether to proceed.</p></div></div></section><section class="detail-steps section-cream"><div class="container"><div class="section-heading split-heading"><div>${sectionLabel('THE JOURNEY')}<h2>What to <em>expect.</em></h2></div><p>Every appointment and procedure differs. These are general consultation milestones, not a guarantee of clinical outcomes.</p></div><div class="process-grid">${[['01','Start with you','Talk about what matters to you and what you hope to understand.'],['02','Understand options','Discuss suitability, alternatives and any relevant risks.'],['03','Make your choice','Take time to decide whether any option feels appropriate.'],['04','Plan with care','A qualified practitioner explains next steps and any aftercare.']].map(a=>`<div class="process-step"><span class="process-number">${a[0]} ✳</span><div class="process-rule"></div><h3>${a[1]}</h3><p>${a[2]}</p></div>`).join('')}</div></div></section><section class="detail-faq section-light"><div class="container faq-layout"><div>${sectionLabel('GOOD QUESTIONS FIRST')}<h2>Worth <em>asking.</em></h2><p>Information here is illustrative. Ask a qualified practitioner for advice tailored to you.</p></div><div class="faqs">${questions.map(([q,a],i)=>`<details ${i===0?'open':''}><summary><span>0${i+1}</span>${q}<i>${icons.plus}</i></summary><p>${a}</p></details>`).join('')}</div></div></section><section class="related-section section-dark"><div class="container"><div class="section-heading split-heading inverse"><div>${sectionLabel('YOU MIGHT ALSO EXPLORE')}<h2>There is always<br><em>more to discover.</em></h2></div>${arrowLink('ALL TREATMENTS','/treatments','on-dark')}</div><div class="treatment-grid">${(related.length?related:treatments.slice(0,3)).map(card).join('')}</div></div></section>${ctaBand()}`;}
const galleryItems=[
 ['Skin',PHOTOS.facial,'interior','The treatment moment'],
 ['Beauty',PHOTOS.hero,'portrait','Beautifully individual'],
 ['Spaces',PHOTOS.serenity,'interior','A quiet escape'],
 ['Details',PHOTOS.products,'serum','The daily ritual'],
 ['Beauty',PHOTOS.portraitSoft,'portrait','Natural radiance'],
 ['Skin',PHOTOS.skincare,'serum','Modern skin essentials'],
 ['Spaces',PHOTOS.studio,'interior','Design for wellbeing'],
 ['Details',PHOTOS.ritual,'interior','Thoughtful touch'],
 ['Beauty',PHOTOS.muse,'portrait','True to yourself'],
 ['Skin',PHOTOS.texture,'serum','A softer perspective'],
 ['Details',PHOTOS.beauty,'portrait','Beauty in focus'],
 ['Beauty',PHOTOS.portrait,'portrait','The human touch']
];
function galleryPage(){return `${pageHero('THE VISUAL JOURNAL','Beauty, through','a different lens.','An editorial collection of the shapes, moods and moments that inspire our universe.')}<section class="gallery-section section-light"><div class="container"><div class="gallery-toolbar">${sectionLabel('THE GALLERY')}<div class="filter-bar">${['All','Skin','Beauty','Spaces','Details'].map(c=>`<button class="filter-btn ${activeGallery===c?'active':''}" data-gallery-filter="${c}">${c}</button>`).join('')}</div></div><div class="gallery-grid" id="gallery-grid">${galleryItems.map(([category,photo,bak,name],i)=>`<button class="gallery-tile gallery-size-${i%5}" data-gallery-img="${i}" aria-label="View ${name}, editorial demo image" ${activeGallery!=='All'&&category!==activeGallery?'hidden':''}>${img(photo,bak,'',name)}<span><small>${category.toUpperCase()} / ${String(i+1).padStart(2,'0')}</small><b>${name}</b><i>↗</i></span></button>`).join('')}</div><p class="fineprint">These are illustrative editorial visuals, not photographs of an actual Aesthetics Universe clinic or patients.</p></div></section><section class="compare-section section-cream"><div class="container compare-layout"><div>${sectionLabel('INTERACTIVE COMPARISON DEMO')}<h2>Notice the<br><em>little details.</em></h2><p>Move the slider to see how a different lighting treatment changes the same illustrative portrait. This demonstrates an interactive comparison feature — <strong>not</strong> a clinical before-and-after result.</p><span class="compare-legend">✳ &nbsp; SAME PORTRAIT · TWO COLOUR GRADES</span></div><div class="compare-area"><div class="compare-frame" id="compare-frame" style="--reveal:${compareValue}%"><div class="compare-base">${img(PHOTOS.hero,'portrait','','Editorial portrait with neutral colour grading')}</div><div class="compare-overlay">${img(PHOTOS.hero,'portrait','','Same illustrative portrait with a warmer colour grade')}</div><div class="compare-divider"><span>↔</span></div><span class="compare-label compare-left">ORIGINAL LIGHT</span><span class="compare-label compare-right">WARM LIGHT</span></div><label for="compare-range">Adjust lighting comparison</label><input type="range" id="compare-range" min="0" max="100" value="${compareValue}" aria-label="Reveal warmer colour grading"/></div></div></section>${ctaBand()}`;}
function aboutPage(){return `${pageHero('THE WORLD BEHIND THE NAME','Beauty belongs','to everyone.','A fresh perspective on aesthetics — where discovery feels personal and every individual matters.')}<section class="about-lead section-light"><div class="container about-lead-grid"><div class="about-images"><div>${img(PHOTOS.muse,'portrait','','Natural light editorial portrait')}</div><div>${img(PHOTOS.products,'serum','','Editorial skincare still life')}</div><span>AN UNIVERSE OF POSSIBILITY</span></div><div class="about-text">${sectionLabel('OUR PHILOSOPHY')}<h2>We see beauty<br><em>differently.</em></h2><p>Aesthetics Universe was imagined around a simple belief: meaningful beauty experiences should celebrate individuality, not erase it.</p><p>This fictional brand concept combines a thoughtful clinical-inspired experience with the warmth and elegance of luxury beauty storytelling.</p><p>It is a demonstration of what a distinctive, modern aesthetics website could feel like — and the starting point for a bigger creative conversation.</p>${arrowLink('EXPLORE THE EXPERIENCE','/universe')}</div></div></section>${process()}<section class="values-section section-dark"><div class="container"><div class="section-heading split-heading inverse"><div>${sectionLabel('WHAT GUIDES THE EXPERIENCE')}<h2>Made of the<br><em>things that matter.</em></h2></div><p>Good aesthetics experiences are built around trust, clarity and an appreciation of individual choice.</p></div><div class="values-grid">${[['01','Individuality','No single definition of beauty. Your goals, your preferences and your pace.'],['02','Thoughtfulness','Real understanding comes before any decision or procedure.'],['03','Transparency','Clear conversations about expectations, alternatives and risks.']].map(v=>`<div><span>${v[0]} / ✳</span><h3>${v[1]}</h3><p>${v[2]}</p></div>`).join('')}</div></div></section>${ctaBand()}`;}
function finderSection(){return `<section class="finder-section section-dark"><div class="container finder-grid"><div>${sectionLabel('A PATH THAT BEGINS WITH YOU')}<h2>What would you<br><em>like to explore?</em></h2><p>A simple discovery experience. Choose an interest and explore some related information — not a personalised recommendation.</p><span class="finder-side-note">01 / SELECT WHAT SPARKS YOUR CURIOSITY</span></div><div class="finder-card"><div class="finder-head"><span>YOUR DISCOVERY PATH</span><span>✳ &nbsp; EXPLORE</span></div><h3>What brings<br>you here today?</h3><div class="finder-options">${interests.map(x=>`<button type="button" data-interest="${x.id}">${x.name} <span>↗</span></button>`).join('')}</div><div id="finder-result" class="finder-result"><p>Select one of the interests above to see related treatment information.</p></div><span class="finder-disclaimer">FOR DISCOVERY ONLY. CLINICAL SUITABILITY REQUIRES A PROFESSIONAL CONSULTATION.</span></div></div></section>`;}
function universePage(){return `${pageHero('EXPLORE THE UNIVERSE','Every journey has','its own orbit.','Choose a world to discover how the art of aesthetics can be approached through your own interests.')} ${universeSection(true)}${finderSection()}<section class="universe-journey section-light"><div class="container info-grid"><div>${sectionLabel('A NOTE ON DISCOVERY')}<h2>Explore with curiosity.<br><em>Choose with care.</em></h2></div><div><p>This explorer helps you navigate illustrative service categories. It does not assess medical suitability or recommend treatments.</p><p>Real treatment decisions should always be made with the guidance of a qualified professional who can consider your personal circumstances.</p>${arrowLink('SEE ALL TREATMENTS','/treatments')}</div></div></section>${featured()}${ctaBand()}`;}
function contactPage(){return `${pageHero('LET’S START A CONVERSATION','Curiosity looks','good on you.','Explore our enquiry form and booking demonstration. No messages are sent and no appointments are made.')}<section class="contact-section section-light"><div class="container contact-grid"><div class="contact-info">${sectionLabel('FIND YOUR WAY')}<h2>There’s a whole world<br><em>to discover.</em></h2><p>This is a fictional UK aesthetics brand concept. The contact information below is illustrative only.</p><div class="contact-details"><div><span>LOCATION</span><strong>London, United Kingdom</strong><small>Demonstration location only</small></div><div><span>OPENING HOURS</span><strong>By appointment</strong><small>Sample schedule, not actual availability</small></div><div><span>EMAIL</span><strong>Not connected</strong><small>Use the demo form to explore the interface</small></div></div><div class="contact-art"><div class="orbit-small"></div><span>✳</span><b>LET'S DISCOVER<br>WHAT'S POSSIBLE</b></div></div><div class="contact-form-wrap"><span class="contact-form-index">ENQUIRY / 001</span><h3>Make an enquiry.</h3><p>See how a clinic enquiry experience could work. This form does not send or store your details.</p><form id="contact-form" class="contact-form"><div class="form-two"><label>Your name<input type="text" name="name" placeholder="First and last name" autocomplete="name" required maxlength="100"/></label><label>Email address<input type="email" name="email" placeholder="you@example.com" autocomplete="email" required/></label></div><label>What interests you?<select name="interest" required><option value="">Choose an interest</option>${treatments.map(t=>`<option value="${t.slug}">${t.name}</option>`).join('')}<option value="general">Just exploring</option></select></label><label>Your message<textarea name="message" rows="4" placeholder="Tell us a little about what you’re exploring..." minlength="10" maxlength="1000" required></textarea></label><div class="form-bottom"><span>DEMO ONLY. DETAILS ARE NOT TRANSMITTED.</span><button type="submit" class="btn btn-primary">PREVIEW ENQUIRY ${icons.arrowDiag}</button></div></form><div id="contact-confirm" hidden class="form-confirm"><span>✳</span><h4>Your demo enquiry is complete.</h4><p>No message was sent and no details were saved. This is an example of the confirmation a real site could show.</p><button type="button" data-reset-contact>START AGAIN ↗</button></div></div></div></section>${faqBlock()}${ctaBand()}`;}
function editorialCreditsPage(){return `${pageHero('BEHIND THE PHOTOGRAPHY','The images','behind the story.','Our visual references, image licensing and honest approach to illustration.')}<section class="info-page section-light"><div class="container info-grid"><div>${sectionLabel('IMAGE CREDITS')}<h2>Beautiful imagery.<br><em>Used responsibly.</em></h2></div><div><p>The photographs on this website are genuine editorial and stock photography served from Unsplash. They show real people, products and settings, but <strong>do not represent real Aesthetics Universe practitioners, customers, facilities or clinical outcomes.</strong></p><p>Photography is used under the <a href="https://unsplash.com/license" target="_blank" rel="noopener noreferrer">Unsplash License ↗</a>. Attribution is appreciated but not required. Before launching a commercial clinic website, confirm identifiable people’s permissions where needed and replace demo photographs with approved clinic photography.</p><p>Our interactive lighting slider applies different colour treatments to the <strong>same photograph</strong> and is not evidence of a medical treatment result.</p><p><a href="https://unsplash.com" target="_blank" rel="noopener noreferrer">Discover Unsplash and its photographers ↗</a></p>${arrowLink('BACK TO THE GALLERY','/gallery')}</div></div></section>`;}
function privacyPage(){return `${pageHero('DEMONSTRATION SITE NOTICE','A little clarity','goes a long way.','Important information about this front-end website concept.')}<section class="info-page section-light"><div class="container info-grid"><div>${sectionLabel('PRIVACY & TERMS')}<h2>Made to explore.<br><em>Not to collect.</em></h2></div><div><h3>This is a demonstration website.</h3><p>Aesthetics Universe is not currently an operating medical aesthetics clinic. Services, booking times, addresses and client experiences shown are examples only. No treatments are provided through this site.</p><h3>Forms and bookings</h3><p>The enquiry form and booking experience operate within your browser. Submitting them does not send your information to us, save it to a database or make a reservation. Please do not enter personal health or sensitive information.</p><h3>Photography and third parties</h3><p>Photos are loaded from Unsplash and typefaces are loaded from Google Fonts. These services may receive technical data such as IP address when your browser requests their files. We do not embed analytics or advertising trackers.</p><h3>Clinical information</h3><p>Descriptions are general educational examples, not medical advice. Consult an appropriately qualified practitioner before any treatment decision.</p>${arrowLink('CONTACT PAGE','/contact')}</div></div></section>`;}
function notFound(){return `<section class="notfound section-dark"><div class="container">${sectionLabel('YOU HAVE LEFT THE ORBIT')}<h1>Lost in the<br><em>universe?</em></h1><p>That page does not exist, but there is plenty more to discover.</p><a class="btn btn-light" data-link href="/">RETURN HOME ${icons.arrowDiag}</a></div></section>`;}
function modalMarkup(){return `<dialog id="booking-dialog" class="modal booking-dialog" aria-labelledby="booking-title"><div class="dialog-top"><span>✳ &nbsp; AESTHETICS UNIVERSE</span><button type="button" data-close-dialog aria-label="Close booking demonstration">${icons.close}</button></div><div class="dialog-inner"><span class="dialog-step">BOOKING EXPERIENCE / 001</span><h2 id="booking-title">Begin your<br><em>journey.</em></h2><p>Explore how online consultation booking could feel. <strong>This is a demonstration; no real slots or appointments exist.</strong></p><form id="booking-form"><label>Choose an interest<select name="treatment" required><option value="">Select a treatment</option>${treatments.map(t=>`<option value="${t.slug}">${t.name}</option>`).join('')}</select></label><label>Preferred date<input type="date" name="date" id="booking-date" required /></label><label>Example time slot<div class="booking-times">${['10:00','11:30','14:00','16:30'].map((v,i)=>`<label><input type="radio" name="time" value="${v}" ${i===0?'required':''}/><span>${v}</span></label>`).join('')}</div></label><button class="btn btn-primary dialog-submit" type="submit">PREVIEW BOOKING ${icons.arrowDiag}</button></form><div id="booking-confirm" class="booking-confirm" hidden><span class="confirm-star">✳</span><h3>Beautiful beginnings.</h3><p id="booking-confirm-text">You have explored the booking demo.</p><p><strong>No appointment has been made.</strong> This confirmation exists only within your browser.</p><button class="btn btn-primary" type="button" data-close-dialog>BACK TO THE WEBSITE ${icons.arrowDiag}</button></div></div><div class="dialog-footer">DEMONSTRATION ONLY · NO PERSONAL DETAILS REQUESTED</div></dialog><dialog id="lightbox" class="modal lightbox" aria-label="Editorial gallery image"><button type="button" data-close-dialog class="lightbox-close" aria-label="Close image">${icons.close}</button><div class="lightbox-photo"></div><div class="lightbox-caption"></div><div class="lightbox-nav"><button type="button" data-light-prev aria-label="Previous image">←</button><span id="lightbox-counter"></span><button type="button" data-light-next aria-label="Next image">→</button></div></dialog>`;}
function currentPath(){if(window.location.protocol==='file:')return window.location.hash.startsWith('#/')?decodeURI(window.location.hash.slice(1)):'/';let p=decodeURI(window.location.pathname);return p.length>1?p.replace(/\/$/,''):p;}
function render(){const path=currentPath();let content='';let title='Aesthetics Universe | A New Perspective on Beauty';if(path==='/') content=homePage();else if(path==='/treatments') {content=treatmentPage();title='Treatments | Aesthetics Universe';}else if(path.startsWith('/treatments/')){const slug=path.split('/')[2];const t=treatments.find(t=>t.slug===slug);content=t?treatmentDetail(t):notFound();title=t?`${t.name} | Aesthetics Universe`:'Page Not Found | Aesthetics Universe';}else if(path==='/universe'){content=universePage();title='Explore Your Universe | Aesthetics Universe';}else if(path==='/gallery'){content=galleryPage();title='Gallery | Aesthetics Universe';}else if(path==='/about'){content=aboutPage();title='Our Story | Aesthetics Universe';}else if(path==='/contact'){content=contactPage();title='Contact | Aesthetics Universe';}else if(path==='/photography'){content=editorialCreditsPage();title='Photography & Credits | Aesthetics Universe';}else if(path==='/privacy'){content=privacyPage();title='Privacy & Demonstration Notice | Aesthetics Universe';}else {content=notFound();title='Page Not Found | Aesthetics Universe';}document.title=title;ROOT.innerHTML=header(path)+`<main id="main-content">${content}</main>`+footer()+modalMarkup();wireImages();wireCompare();setDates();setScrollHeader();}
function navigate(path){if(currentPath()===path){window.scrollTo({top:0,behavior:'smooth'});return;} if(window.location.protocol==='file:'){window.location.hash='#'+path;}else{history.pushState({},'',path);}render();window.scrollTo({top:0,behavior:'instant'});}
function wireImages(){document.querySelectorAll('img[data-fallback]').forEach(image=>{
 const showFallback=()=>{if(!image.dataset.didFallback){image.dataset.didFallback='1';image.removeAttribute('srcset');image.removeAttribute('sizes');image.src=image.dataset.fallback;}};
 image.addEventListener('error',showFallback,{once:true});
 if(image.complete&&image.naturalWidth===0)showFallback();
});}
function wireCompare(){const range=document.getElementById('compare-range');if(range){range.addEventListener('input',e=>{compareValue=Number(e.target.value);document.getElementById('compare-frame').style.setProperty('--reveal',compareValue+'%');});}}
function setDates(){const el=document.getElementById('booking-date');if(el){const d=new Date();const local=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10);el.min=local;el.value=local;}}
function setScrollHeader(){document.getElementById('site-header')?.classList.toggle('scrolled',window.scrollY>25);}
function openBooking(){const dlg=document.getElementById('booking-dialog');if(!dlg)return;dlg.querySelector('form').hidden=false;dlg.querySelector('#booking-confirm').hidden=true;dlg.showModal();}
let galleryIndex=0;
function visibleGalleryIndices(){return galleryItems.map((g,i)=>({category:g[0],index:i})).filter(g=>activeGallery==='All'||g.category===activeGallery).map(g=>g.index);}
function moveGallery(direction){const visible=visibleGalleryIndices();if(!visible.length)return;const pos=visible.indexOf(galleryIndex);galleryIndex=visible[(pos+direction+visible.length)%visible.length];updateImage();}
function openImage(idx){galleryIndex=idx;updateImage();document.getElementById('lightbox')?.showModal();}
function updateImage(){const [category,src,bak,name]=galleryItems[galleryIndex];const photo=document.querySelector('.lightbox-photo');if(!photo)return;photo.innerHTML=img(src,bak,'',`${name} editorial example image`);photo.nextElementSibling.textContent=`${category.toUpperCase()} / ${name} · DEMONSTRATION IMAGE`;document.getElementById('lightbox-counter').textContent=`${galleryIndex+1} / ${galleryItems.length}`;wireImages();}
function setMenu(open){const nav=document.getElementById('site-header');nav?.classList.toggle('menu-open',open);const toggle=nav?.querySelector('[data-menu]');if(toggle){toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close menu':'Open menu');}}
document.addEventListener('click',e=>{
 if(e.target.closest('[data-top]')){e.preventDefault();window.scrollTo({top:0,behavior:'smooth'});return;}
 const interest=e.target.closest('[data-interest]');if(interest){document.querySelectorAll('[data-interest]').forEach(b=>b.classList.toggle('active',b===interest));const item=interests.find(x=>x.id===interest.dataset.interest);const target=document.getElementById('finder-result');target.innerHTML=`<span>YOUR EXPLORATION</span><h4>${item.name}</h4><p>${item.summary}</p><div>${item.links.map(slug=>{const t=treatments.find(t=>t.slug===slug);return `<a data-link href="/treatments/${slug}">${t.name} ↗</a>`;}).join('')}</div><small>These are related topics, not recommendations or an assessment of suitability.</small>`;return;}
 const link=e.target.closest('a[data-link]');if(link){if(e.button===0&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey){e.preventDefault();navigate(link.getAttribute('href'));}return;}
 if(e.target.closest('[data-menu]')){setMenu(!document.getElementById('site-header').classList.contains('menu-open'));return;}
 if(e.target.closest('[data-book]')){setMenu(false);openBooking();return;}
 if(e.target.closest('[data-close-dialog]')){e.target.closest('dialog')?.close();return;}
 const galaxy=e.target.closest('[data-galaxy]');if(galaxy){selectedGalaxy=galaxy.dataset.galaxy;const g=galaxies.find(g=>g.id===selectedGalaxy);document.getElementById('galaxy-panel').innerHTML=galaxyPanel(g);document.querySelectorAll('[data-galaxy]').forEach(b=>{b.classList.toggle('selected',b.dataset.galaxy===selectedGalaxy);b.classList.toggle('active',b.dataset.galaxy===selectedGalaxy);b.setAttribute('aria-pressed',String(b.dataset.galaxy===selectedGalaxy));});return;}
 const tf=e.target.closest('[data-treatment-filter]');if(tf){activeTreatments=tf.dataset.treatmentFilter;document.querySelectorAll('[data-treatment-filter]').forEach(b=>b.classList.toggle('active',b===tf));document.getElementById('catalogue-grid').innerHTML=treatments.filter(t=>activeTreatments==='All'||t.category===activeTreatments).map(card).join('');wireImages();return;}
 const gf=e.target.closest('[data-gallery-filter]');if(gf){activeGallery=gf.dataset.galleryFilter;document.querySelectorAll('[data-gallery-filter]').forEach(b=>b.classList.toggle('active',b===gf));document.querySelectorAll('[data-gallery-img]').forEach(b=>b.hidden=activeGallery!=='All'&&galleryItems[Number(b.dataset.galleryImg)][0]!==activeGallery);return;}
 const gallery=e.target.closest('[data-gallery-img]');if(gallery){openImage(Number(gallery.dataset.galleryImg));return;}
 if(e.target.closest('[data-light-prev]')){moveGallery(-1);return;}
 if(e.target.closest('[data-light-next]')){moveGallery(1);return;}
 if(e.target.closest('[data-reset-contact]')){document.getElementById('contact-form').reset();document.getElementById('contact-form').hidden=false;document.getElementById('contact-confirm').hidden=true;}
});
document.addEventListener('submit',e=>{
 if(e.target.id==='booking-form'){e.preventDefault();const d=new FormData(e.target);const date=d.get('date'),time=d.get('time'),slug=d.get('treatment');if(!date||!time||!slug){e.target.reportValidity();return;}const name=treatments.find(t=>t.slug===slug)?.name||'Consultation';document.getElementById('booking-confirm-text').textContent=`You selected ${name} for ${new Date(date+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'})} at ${time}.`;e.target.hidden=true;document.getElementById('booking-confirm').hidden=false;}
 if(e.target.id==='contact-form'){e.preventDefault();e.target.hidden=true;document.getElementById('contact-confirm').hidden=false;}
});
document.addEventListener('keydown',e=>{const dlg=document.getElementById('lightbox');if(dlg?.open){if(e.key==='ArrowLeft'){moveGallery(-1);}if(e.key==='ArrowRight'){moveGallery(1);}}if(e.key==='Escape')setMenu(false);});
window.addEventListener('popstate',()=>{render();window.scrollTo(0,0);});
window.addEventListener('hashchange',()=>{if(window.location.protocol==='file:'){render();window.scrollTo(0,0);}});
window.addEventListener('scroll',setScrollHeader,{passive:true});
render();
